package com.andye.warmod.menu;
import com.andye.warmod.WarMod;import java.util.UUID;import net.fabricmc.fabric.api.menu.v1.ExtendedMenuType;import net.minecraft.core.BlockPos;import net.minecraft.core.Registry;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.resources.Identifier;
public final class ModMenus{public record SiloOpeningData(BlockPos centre,UUID siloId){public static final StreamCodec<RegistryFriendlyByteBuf,SiloOpeningData> STREAM_CODEC=StreamCodec.of((b,d)->{b.writeBlockPos(d.centre);b.writeUUID(d.siloId);},b->new SiloOpeningData(b.readBlockPos(),b.readUUID()));}public record PhalanxOpeningData(BlockPos centre){public static final StreamCodec<RegistryFriendlyByteBuf,PhalanxOpeningData> STREAM_CODEC=StreamCodec.of((b,d)->b.writeBlockPos(d.centre),b->new PhalanxOpeningData(b.readBlockPos()));}public static final ExtendedMenuType<MissileSiloMenu,SiloOpeningData> MISSILE_SILO=new ExtendedMenuType<>((id,inventory,data)->new MissileSiloMenu(id,inventory,data),SiloOpeningData.STREAM_CODEC);public static final ExtendedMenuType<PhalanxMenu,PhalanxOpeningData> PHALANX=new ExtendedMenuType<>((id,inventory,data)->new PhalanxMenu(id,inventory,data),PhalanxOpeningData.STREAM_CODEC);private static boolean registered;private ModMenus(){}public static void register(){if(registered)return;Registry.register(BuiltInRegistries.MENU,Identifier.fromNamespaceAndPath(WarMod.MOD_ID,"missile_silo"),MISSILE_SILO);Registry.register(BuiltInRegistries.MENU,Identifier.fromNamespaceAndPath(WarMod.MOD_ID,"phalanx_turret"),PHALANX);registered=true;}}
